-- EduNova v0.41.1 Phase 6 maximum depth: cashier control, sponsor agreements and governed payment plans.
CREATE TABLE IF NOT EXISTS student_finance_cash_sessions (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,cashier_id VARCHAR(64) NOT NULL,currency VARCHAR(8) NOT NULL,opening_float_minor INTEGER NOT NULL CHECK(opening_float_minor>=0),state VARCHAR(20) NOT NULL,opened_at TIMESTAMP NOT NULL,closed_at TIMESTAMP NULL,expected_minor INTEGER NULL,counted_minor INTEGER NULL,variance_minor INTEGER NULL,close_note VARCHAR(1000) NULL);
CREATE INDEX IF NOT EXISTS ix_finance_cash_open ON student_finance_cash_sessions(institution_id,cashier_id,state,opened_at);
CREATE TABLE IF NOT EXISTS student_finance_sponsor_agreements (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,name VARCHAR(200) NOT NULL,reference VARCHAR(100) NOT NULL,currency VARCHAR(8) NOT NULL,ceiling_minor INTEGER NOT NULL CHECK(ceiling_minor>0),used_minor INTEGER NOT NULL DEFAULT 0 CHECK(used_minor>=0 AND used_minor<=ceiling_minor),valid_from DATE NOT NULL,valid_until DATE NOT NULL,state VARCHAR(20) NOT NULL,created_by VARCHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL,CONSTRAINT uq_sponsor_agreement_ref UNIQUE(institution_id,reference));
CREATE TABLE IF NOT EXISTS student_finance_payment_plans (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,registration_id VARCHAR(64) NOT NULL,name VARCHAR(160) NOT NULL,approved_by VARCHAR(64) NOT NULL,reason VARCHAR(1000) NOT NULL,created_at TIMESTAMP NOT NULL,CONSTRAINT uq_registration_payment_plan UNIQUE(registration_id));
CREATE TABLE IF NOT EXISTS student_finance_payment_plan_lines (id VARCHAR(64) PRIMARY KEY,plan_id VARCHAR(64) NOT NULL,sequence_no INTEGER NOT NULL CHECK(sequence_no>0),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),due_on DATE NOT NULL,CONSTRAINT uq_payment_plan_line UNIQUE(plan_id,sequence_no));
